CREATE TABLE users(id uuid PRIMARY KEY, email text NOT NULL UNIQUE, full_name text NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('superadmin','finance_admin','cashier','hardware_tech','software_dev')),is_active boolean NOT NULL DEFAULT true);
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE login_attempts(key text PRIMARY KEY, attempts int NOT NULL, window_start timestamptz NOT NULL);
CREATE TABLE customers(id uuid PRIMARY KEY,full_name text NOT NULL,phone_number text NOT NULL UNIQUE,email text,address text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory(id uuid PRIMARY KEY,sku text NOT NULL UNIQUE,name text NOT NULL,category text NOT NULL CHECK(category IN ('accessory','sparepart','raw_material_print','consumable')),cost_price numeric(15,2) NOT NULL CHECK(cost_price>=0),sale_price numeric(15,2) NOT NULL CHECK(sale_price>0),current_stock int NOT NULL DEFAULT 0 CHECK(current_stock>=0),minimum_threshold int NOT NULL DEFAULT 5 CHECK(minimum_threshold>=0),unit_of_measure text NOT NULL DEFAULT 'pcs',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(code text PRIMARY KEY,name text NOT NULL);
INSERT INTO accounts VALUES ('1101','Cash'),('1102','Bank'),('1103','Accounts receivable'),('1104','Inventory'),('3101','Stock adjustment equity'),('4100','Retail revenue'),('4101','Service revenue'),('4201','Agency earned revenue'),('5100','Cost of goods sold');
CREATE TABLE journals(id uuid PRIMARY KEY,reference_type text NOT NULL,reference_id uuid NOT NULL,memo text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),creation_tx bigint NOT NULL DEFAULT txid_current());
CREATE TABLE journal_lines(id uuid PRIMARY KEY,journal_id uuid NOT NULL REFERENCES journals(id),account_code text NOT NULL REFERENCES accounts(code),debit numeric(15,2) NOT NULL CHECK(debit>=0),credit numeric(15,2) NOT NULL CHECK(credit>=0),CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable record' USING ERRCODE='23514'; END $$;
CREATE TRIGGER journal_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON journals FOR EACH STATEMENT EXECUTE FUNCTION immutable_record();
CREATE TRIGGER line_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON journal_lines FOR EACH STATEMENT EXECUTE FUNCTION immutable_record();
CREATE FUNCTION new_journal_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM journals WHERE id=NEW.journal_id AND creation_tx=txid_current()) THEN RAISE EXCEPTION 'Cannot append to posted journal' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER line_new BEFORE INSERT ON journal_lines FOR EACH ROW EXECUTE FUNCTION new_journal_only();
CREATE FUNCTION verify_balance() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE jid uuid; n bigint; d numeric; c numeric; BEGIN IF TG_TABLE_NAME='journals' THEN jid=NEW.id; ELSE jid=NEW.journal_id; END IF; SELECT count(*),coalesce(sum(debit),0),coalesce(sum(credit),0) INTO n,d,c FROM journal_lines WHERE journal_id=jid; IF n<2 OR d<>c THEN RAISE EXCEPTION 'Unbalanced or empty journal' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER journal_balance AFTER INSERT ON journals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION verify_balance();
CREATE CONSTRAINT TRIGGER line_balance AFTER INSERT ON journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION verify_balance();
CREATE TABLE stock_movements(id uuid PRIMARY KEY,item_id uuid NOT NULL REFERENCES inventory(id),quantity int NOT NULL CHECK(quantity<>0),balance int NOT NULL CHECK(balance>=0),reason text NOT NULL,reference_id uuid NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER stock_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON stock_movements FOR EACH STATEMENT EXECUTE FUNCTION immutable_record();
CREATE TABLE orders(id uuid PRIMARY KEY,order_number text UNIQUE NOT NULL,customer_id uuid REFERENCES customers(id),total_amount numeric(15,2) NOT NULL CHECK(total_amount>0),items jsonb NOT NULL,created_by uuid NOT NULL REFERENCES users(id),idempotency_key text NOT NULL,request_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(created_by,idempotency_key));
CREATE TABLE repairs(id uuid PRIMARY KEY,ticket_number text NOT NULL UNIQUE,customer_id uuid NOT NULL REFERENCES customers(id),device_type text NOT NULL,brand text NOT NULL,model_name text NOT NULL,declared_defects text NOT NULL,current_state text NOT NULL DEFAULT 'ticket_created' CHECK(current_state IN ('ticket_created','inspection_pending','diagnosed_quotation_ready','waiting_customer_approval','repair_approved_in_progress','waiting_spareparts','qa_qc_validation','ready_for_pickup','delivered_closed','cancelled_unrepairable')),quotation_amount numeric(15,2) CHECK(quotation_amount>0),quotation_description text,intake_evidence text,approval_evidence text,qc_evidence text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE repair_transitions(id uuid PRIMARY KEY,repair_id uuid NOT NULL REFERENCES repairs(id),from_state text NOT NULL,to_state text NOT NULL,evidence jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER repair_audit_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON repair_transitions FOR EACH STATEMENT EXECUTE FUNCTION immutable_record();
CREATE TABLE projects(id uuid PRIMARY KEY,project_code text NOT NULL UNIQUE,customer_id uuid NOT NULL REFERENCES customers(id),title text NOT NULL,total_contract_value numeric(15,2) NOT NULL CHECK(total_contract_value>0),target_delivery_date date NOT NULL,scope_description text NOT NULL,status text NOT NULL DEFAULT 'contract_active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices(id uuid PRIMARY KEY,invoice_number text UNIQUE NOT NULL,customer_id uuid REFERENCES customers(id),source_module text NOT NULL CHECK(source_module IN ('pos','service','agency')),source_id uuid NOT NULL,total_amount numeric(15,2) NOT NULL CHECK(total_amount>0),paid_amount numeric(15,2) NOT NULL DEFAULT 0 CHECK(paid_amount>=0 AND paid_amount<=total_amount),status text NOT NULL DEFAULT 'issued' CHECK(status IN ('issued','partially_paid','paid')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_module,source_id),CHECK((status='paid')=(paid_amount=total_amount)));
CREATE TABLE milestones(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),name text NOT NULL,amount numeric(15,2) NOT NULL CHECK(amount>0),status text NOT NULL DEFAULT 'unbilled',invoice_id uuid REFERENCES invoices(id),completed_at timestamptz);
CREATE TABLE payments(id uuid PRIMARY KEY,invoice_id uuid NOT NULL REFERENCES invoices(id),amount numeric(15,2) NOT NULL CHECK(amount>0),payment_method text NOT NULL CHECK(payment_method IN ('cash','manual_transfer')),payment_reference text NOT NULL UNIQUE,received_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER payment_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON payments FOR EACH STATEMENT EXECUTE FUNCTION immutable_record();
CREATE INDEX journal_lines_entry ON journal_lines(journal_id);
CREATE INDEX invoices_source ON invoices(source_id);
CREATE INDEX milestones_project ON milestones(project_id);
CREATE INDEX sessions_expiration ON sessions(expires_at);
